275	                <thead>
276	                  <tr className="bg-gray-50 border-b border-gray-100">
277	                    {['Date','Total Minutes','Target','Compliance','RN Minutes','RN Target','RN %','Status','Penalty'].map(h => (
278	                      <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>
279	                    ))}
280	                  </tr>
281	                </thead>
282	                <tbody>
283	                  {periodData.days.map((day, idx) => (
284	                    <tr key={day.date} className={`border-b border-gray-50 hover:bg-green-50/20 transition-colors ${idx % 2 === 1 ? 'bg-gray-50/40' : ''}`}>
285	                      <td className="px-4 py-3 font-medium text-gray-900 whitespace-nowrap">{toDisplay(day.date)}</td>
286	                      <td className="px-4 py-3 text-gray-700">{day.totalMinutes.toLocaleString()}</td>
287	                      <td className="px-4 py-3 text-gray-500">{day.targetMinutes.toLocaleString()}</td>
288	                      <td className="px-4 py-3 font-semibold" style={{ color: day.ragStatus === 'GREEN' ? '#22c55e' : day.ragStatus === 'AMBER' ? '#f59e0b' : '#ef4444' }}>
289	                        {formatPct(day.compliancePct)}
290	                      </td>
291	                      <td className="px-4 py-3 text-gray-700">{day.rnMinutes.toLocaleString()}</td>
292	                      <td className="px-4 py-3 text-gray-500">{day.rnTargetMinutes.toLocaleString()}</td>
293	                      <td className="px-4 py-3 font-semibold" style={{ color: day.rnRagStatus === 'GREEN' ? '#22c55e' : day.rnRagStatus === 'AMBER' ? '#f59e0b' : '#ef4444' }}>
294	                        {formatPct(day.rnCompliancePct)}
295	                      </td>
296	                      <td className="px-4 py-3">
297	                        <span className={`px-2 py-0.5 rounded text-xs font-bold ${
298	                          day.ragStatus === 'GREEN' ? 'bg-green-100 text-green-700' :
299	                          day.ragStatus === 'AMBER' ? 'bg-amber-100 text-amber-700' :
300	                          'bg-red-100 text-red-700'
301	                        }`}>{day.ragStatus}</span>
302	                      </td>
303	                      <td className="px-4 py-3 font-medium" style={{ color: day.penaltyAmount > 0 ? '#ef4444' : '#6b7280' }}>
304	                        {day.penaltyAmount > 0 ? formatAUD(day.penaltyAmount) : '—'}
305	                      </td>
306	                    </tr>
307	                  ))}
308	                </tbody>
309	              </table>
310	            </div>
311	          </div>
312	
313	        </div>
314	      )}
315	
316	      {/* Empty state */}
317	      {!generated && (
318	        <div className="text-center py-20 bg-white rounded-xl border border-gray-100 shadow-sm">
319	          <FileText className="w-12 h-12 text-gray-300 mx-auto mb-3" />
320	          <p className="text-gray-500 font-medium">No report generated yet</p>
321	          <p className="text-sm text-gray-400 mt-1">Select a date range and click Generate Report</p>
322	        </div>
323	      )}
324	    </div>
325	  );
326	}
