37	  if (days <= 7)  return <span className="px-2 py-0.5 rounded text-xs font-bold bg-red-100 text-red-700" title={fmt}>⚠ {days}d</span>;
38	  if (days <= 30) return <span className="px-2 py-0.5 rounded text-xs font-bold bg-amber-100 text-amber-700" title={fmt}>{days}d</span>;
