'use client';

import { useState, useMemo, useEffect } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ReferenceLine, ResponsiveContainer,
} from 'recharts';
import {
  Users, Clock, TrendingUp, AlertTriangle, Star, ExternalLink,
  CheckCircle, XCircle, Activity, Database, ChevronLeft, ChevronRight,
  Stethoscope, ShieldAlert, ArrowRight,
} from 'lucide-react';
import { facility as dummyFacility, shiftsByDate as dummyShiftsByDate, trendDates as dummyTrendDates, TODAY, staff as dummyStaff } from '@/lib/dummyData';
import {
  calculateDayCompliance,
  calculatePeriodCompliance,
  formatAUD,
  formatPct,
} from '@/lib/compliance';
import { getShifts, mapShift } from '@/lib/db';
import { SEED_FACILITY_ID } from '@/lib/seedData';

// ─── Helpers ─────────────────────────────────────────────────────────────────

function formatDate(isoDate) {
  const [y, m, d] = isoDate.split('-');
  return `${d}/${m}/${y}`;
}

function ragColour(status) {
  if (status === 'GREEN') return '#22c55e';
  if (status === 'AMBER') return '#f59e0b';
  return '#ef4444';
}

function ragBg(status) {
  if (status === 'GREEN') return 'bg-green-100 text-green-800';
  if (status === 'AMBER') return 'bg-amber-100 text-amber-800';
  return 'bg-red-100 text-red-800';
}

// ─── Period filter helpers ─────────────────────────────────────────────────

const PERIODS = [
  { id: 'thisWeek',    label: 'This Week'    },
  { id: 'lastWeek',   label: 'Last Week'    },
  { id: 'thisMonth',  label: 'This Month'   },
  { id: 'thisQuarter',label: 'This Quarter' },
  { id: 'last30',     label: 'Last 30 Days' },
];

function generateDateRange(startISO, endISO) {
  const dates = [];
  const current = new Date(startISO + 'T00:00:00');
  const end = new Date(endISO + 'T00:00:00');
  while (current <= end) {
    dates.push(current.toISOString().split('T')[0]);
    current.setDate(current.getDate() + 1);
  }
  return dates;
}

function getPeriodDates(period, today) {
  const todayD = new Date(today + 'T00:00:00');

  function toISO(d) {
    return d.toISOString().split('T')[0];
  }

  switch (period) {
    case 'thisWeek': {
      const dow = todayD.getDay(); // 0=Sun
      const monday = new Date(todayD);
      monday.setDate(todayD.getDate() - (dow === 0 ? 6 : dow - 1));
      return generateDateRange(toISO(monday), today);
    }
    case 'lastWeek': {
      const dow = todayD.getDay();
      const thisMonday = new Date(todayD);
      thisMonday.setDate(todayD.getDate() - (dow === 0 ? 6 : dow - 1));
      const lastSunday = new Date(thisMonday);

