1	/**
2	 * CareMinutes.ai — Australian Date Utilities
3	 *
4	 * All "today" logic must use the Australia/Sydney IANA timezone identifier.
5	 * This correctly handles AEST (UTC+10, April–October) and
6	 * AEDT (UTC+11, October–April, daylight saving) automatically —
7	 * no manual offset arithmetic needed.
8	 *
9	 * Safe to call on Node.js 18+ (server) and all modern browsers (client).
10	 */
11	
12	/**
13	 * Returns today's date in Australian Eastern Time as YYYY-MM-DD.
14	 * The 'en-CA' locale is used because it reliably emits that format.
15	 *
16	 * @returns {string} e.g. "2026-04-07"
17	 */
18	export function getAustralianToday() {
19	  return new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Sydney' });
20	}
21	
22	/**
23	 * Returns the current Australian time as a human-readable string.
24	 * Useful for logging and display.
25	 *
26	 * @returns {string} e.g. "07/04/2026, 07:00:00 AM"
27	 */
28	export function getAustralianNow() {
29	  return new Date().toLocaleString('en-AU', { timeZone: 'Australia/Sydney' });
30	}
31	
32	/**
33	 * Returns quarter metadata for any ISO date string (YYYY-MM-DD).
34	 *   Q1 = Jan–Mar  |  Q2 = Apr–Jun  |  Q3 = Jul–Sep  |  Q4 = Oct–Dec
35	 *
36	 * @param {string} isoDate — "YYYY-MM-DD"
37	 * @returns {{
38	 *   quarter: number,
39	 *   year: number,
40	 *   start: string,
41	 *   end: string,
42	 *   totalDays: number,
43	 *   label: string,
44	 *   prevQuarterLabel: string,
45	 * }}
46	 */
47	export function getQuarterInfo(isoDate) {
48	  const [y, m] = isoDate.split('-').map(Number);
49	  const q = Math.ceil(m / 3);
50	
51	  const startMonth = (q - 1) * 3 + 1;
52	  const endMonth   = q * 3;
53	
54	  const start = `${y}-${String(startMonth).padStart(2, '0')}-01`;
55	  const lastDay = new Date(y, endMonth, 0).getDate(); // day 0 of next month = last day of this month
56	  const end   = `${y}-${String(endMonth).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
57	
58	  const totalDays =
59	    Math.round((new Date(end + 'T00:00:00') - new Date(start + 'T00:00:00')) / 86400000) + 1;
60	
61	  // Previous quarter label for display (e.g. "Q1 2026")
62	  const prevQ = q === 1 ? 4 : q - 1;
63	  const prevY = q === 1 ? y - 1 : y;
64	  const prevQuarterLabel = `Q${prevQ} ${prevY}`;
65	
66	  return {
67	    quarter: q,
68	    year:    y,
69	    start,
70	    end,
71	    totalDays,
72	    label:            `Q${q} ${y}`,
73	    prevQuarterLabel,
74	  };
75	}
76	
77	/**
78	 * Generates every calendar date between startISO and endISO inclusive.
79	 *
80	 * @param {string} startISO — "YYYY-MM-DD"
81	 * @param {string} endISO   — "YYYY-MM-DD"
82	 * @returns {string[]}
83	 */
84	export function generateDateRange(startISO, endISO) {
85	  const dates = [];
86	  const current = new Date(startISO + 'T00:00:00');
87	  const end     = new Date(endISO   + 'T00:00:00');
88	  while (current <= end) {
89	    dates.push(current.toISOString().split('T')[0]);
90	    current.setDate(current.getDate() + 1);
91	  }
92	  return dates;
93	}
94	
95	/**
96	 * Returns the ISO week number (1–53) for an ISO date string.
97	 * Weeks start on Monday per ISO 8601.
98	 *
99	 * @param {string} isoDate — "YYYY-MM-DD"
100	 * @returns {number}
101	 */
102	export function getISOWeek(isoDate) {
103	  const d = new Date(isoDate);
104	  const day = d.getDay() || 7; // treat Sunday as 7
105	  d.setUTCDate(d.getUTCDate() + 4 - day);
106	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
107	  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
108	}
109	
110	/**
111	 * Returns date filter range objects for the shifts/reports pages,
112	 * computed dynamically relative to a given today.
113	 *
114	 * @param {string} today — "YYYY-MM-DD" in Australian time
115	 * @returns {{ Today, 'This Week', 'Last Week', 'This Month': { from: string, to: string } }}
116	 */
117	export function getFilterRanges(today) {
118	  const todayD = new Date(today + 'T00:00:00');
119	
120	  function toISO(d) {
121	    return d.toISOString().split('T')[0];
122	  }
123	
124	  const dow      = todayD.getDay(); // 0 = Sun
125	  const daysBack = dow === 0 ? 6 : dow - 1; // days back to Monday
126	
127	  const thisMonday = new Date(todayD);
128	  thisMonday.setDate(todayD.getDate() - daysBack);
129	
130	  const thisSunday = new Date(thisMonday);
131	  thisSunday.setDate(thisMonday.getDate() + 6);
132	
133	  const lastMonday = new Date(thisMonday);
134	  lastMonday.setDate(thisMonday.getDate() - 7);
135	
136	  const lastSunday = new Date(thisMonday);
137	  lastSunday.setDate(thisMonday.getDate() - 1);
138	
139	  const firstOfMonth = new Date(todayD.getFullYear(), todayD.getMonth(), 1);
140	  const lastOfMonth  = new Date(todayD.getFullYear(), todayD.getMonth() + 1, 0);
141	
142	  return {
143	    'Today':      { from: today,               to: today               },
144	    'This Week':  { from: toISO(thisMonday),    to: toISO(thisSunday)   },
145	    'Last Week':  { from: toISO(lastMonday),    to: toISO(lastSunday)   },
146	    'This Month': { from: toISO(firstOfMonth),  to: toISO(lastOfMonth)  },
147	  };
148	}
