const filteredDates = useMemo(() => {
  if (!generated) return [];
  try {
    const dates = [];
    // Use T12:00:00 (noon) to avoid UTC conversion flipping the date in
    // Australian timezones (UTC+10/+11) and across DST transitions.
    const cur = new Date(fromDate + 'T12:00:00');
    const end = new Date(toDate   + 'T12:00:00');
    while (cur <= end) {
      const y = cur.getFullYear();
      const m = String(cur.getMonth() + 1).padStart(2, '0');
      const d = String(cur.getDate()).padStart(2, '0');
      dates.push(`${y}-${m}-${d}`);
      cur.setDate(cur.getDate() + 1);
    }
    return dates;
  } catch { return trendDates; }
}, [generated, fromDate, toDate]);

