269	  return Array.from({ length: 24 }, (_, h) => {
270	    const covered = rnShifts.some(sh => {
271	      const [startH] = sh.startTime.split(':').map(Number);
272	      const [endH]   = sh.endTime.split(':').map(Number);
273	      if (endH <= startH) return h >= startH || h < endH;
274	      return h >= startH && h < endH;
275	    });
276	    return { hour: h, covered };
277	  });
278	}
