 * Minimal RAG status badge — dot + label, light background, subtle border.
 * Used across Dashboard, Forecast, Reports, Alerts pages.
 *
 * Props:
 *   status  — 'GREEN' | 'AMBER' | 'RED'
 */
export default function RagBadge({ status }) {
  if (status === 'GREEN') {
    return (
      <span
        className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-xs font-medium text-green-700"
        style={{ background: '#f0fdf4', border: '1px solid #bbf7d0' }}
      >
        <span
          className="shrink-0"
          style={{ width: 6, height: 6, borderRadius: '50%', background: '#16a34a', display: 'inline-block' }}
        />
        Compliant
      </span>
    );
  }
  if (status === 'AMBER') {
    return (
      <span
        className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-xs font-medium text-amber-700"
        style={{ background: '#fffbeb', border: '1px solid #fde68a' }}
      >
        <span
          className="shrink-0"
          style={{ width: 6, height: 6, borderRadius: '50%', background: '#d97706', display: 'inline-block' }}
        />
        At Risk
      </span>
    );
  }
  // RED
  return (
    <span
