'use client';

import { useEffect } from 'react';
import { X } from 'lucide-react';

/**
 * Fullscreen modal overlay for charts.
 *
 * Props:
 *   open      — boolean
 *   onClose   — () => void
 *   title     — string  (modal header title)
 *   children  — React nodes rendered in the modal body (fill full height)
 */
export default function FullscreenModal({ open, onClose, title, children }) {
  // Close on Escape
  useEffect(() => {
    if (!open) return;
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-[60] flex flex-col"
      style={{ background: 'rgba(0,0,0,0.72)' }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div className="flex-1 flex flex-col m-3 md:m-8 bg-white rounded-2xl shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 shrink-0">
          <h2 className="font-semibold text-gray-900">{title}</h2>
          <button
            onClick={onClose}
            className="p-2 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition-colors"
            aria-label="Close fullscreen"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        {/* Body — chart fills this area */}
        <div className="flex-1 min-h-0 p-4 md:p-6 overflow-auto">
          {children}
        </div>
      </div>
    </div>
  );
}

